// Turn Meta's webhook payload into one item per message or comment.
const OWN = ['1080869611776488', '17841420040350345'];
const b = $input.first().json.body || {};
const platform = b.object === 'instagram' ? 'instagram' : 'facebook';
const out = [];
for (const e of b.entry || []) {
  for (const m of e.messaging || []) {
    if (m.message && m.message.is_echo) continue;
    if (OWN.includes(String(m.sender && m.sender.id))) continue;
    const text = (m.message && m.message.text) || (m.postback && (m.postback.title || m.postback.payload)) || '';
    if (!text) continue;
    out.push({ id: (m.message && m.message.mid) || ('pb-' + m.timestamp), platform, kind: 'dm',
      sender_id: String(m.sender.id), comment_id: '', username: '', text,
      received_at: new Date(m.timestamp || Date.now()).toISOString() });
  }
  for (const c of e.changes || []) {
    const v = c.value || {};
    if (c.field === 'comments') {
      if (!v.from || OWN.includes(String(v.from.id))) continue;
      out.push({ id: 'c-' + v.id, platform: 'instagram', kind: 'comment', sender_id: String(v.from.id),
        comment_id: String(v.id), username: v.from.username || '', text: v.text || '',
        received_at: new Date().toISOString() });
    }
    if (c.field === 'feed' && v.item === 'comment' && v.verb === 'add') {
      if (!v.from || OWN.includes(String(v.from.id))) continue;
      out.push({ id: 'c-' + v.comment_id, platform: 'facebook', kind: 'comment', sender_id: String(v.from.id),
        comment_id: String(v.comment_id), username: v.from.name || '', text: v.message || '',
        received_at: new Date((v.created_time || Date.now() / 1000) * 1000).toISOString() });
    }
  }
}
return out.map(json => ({ json }));

// Decide what each message is, what (if anything) to auto-send, and 3 reply options for Graham.
// ---- EDIT THESE ----
const TAKING_CLIENTS = true;               // false = waitlist wording first
const NEXT_OPENING = 'next week';          // e.g. 'in December'
const PRICE_FROM = 'PASTE_PRICE_FROM';     // e.g. '$1,500'. Leave as is to never quote a number
const KIT_URL = 'PASTE_KIT_URL';           // leave as is = no kit replies
const BOOK_URL = 'https://calendly.com/grahamivy-co/30min';  // Calendly. Set to 'PASTE' to use the links page
// --------------------
const CONSULT = BOOK_URL.startsWith('PASTE') ? 'https://openframe.design/links' : BOOK_URL;
const WORK = 'https://openframe.design';
const has = (t, words) => words.some(w => new RegExp('\\b' + w + '\\b', 'i').test(t));
const emailMatch = t => (t.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i) || [''])[0];
const shortId = s => { let h = 5381; for (const ch of s) h = ((h * 33) ^ ch.charCodeAt(0)) >>> 0; return h.toString(36).slice(0, 6); };
// A reply ending in a link is sent as text + a tappable button, so the link never wraps mid-word.
const toMessage = text => {
  const m = String(text || '').match(/^([\s\S]*?)\s*\n\n(https?:\/\/\S+)\s*$/);
  if (!m || !m[1].trim()) return { text };
  const url = m[2];
  const title = url === WORK ? 'See our work' : url === KIT_URL ? 'Get the kit' : 'Book a free consult';
  return { attachment: { type: 'template', payload: { template_type: 'button', text: m[1].trim().replace(/:$/, '.'),
    buttons: [{ type: 'web_url', url, title }] } } };
};
const kitOn = !KIT_URL.startsWith('PASTE');
const priceOn = !PRICE_FROM.startsWith('PASTE');

const OPTIONS = {
  pricing: [
    `Thanks for asking. Every project is scoped a little differently, so every project starts with a free 30-minute consult and give you a real number after. Grab a time here:\n\n${CONSULT}`,
    priceOn
      ? `Projects usually start around ${PRICE_FROM}, depending on scope. Happy to give you an exact number after a free 30-minute consult:\n\n${CONSULT}`
      : `Happy to give you a number. Could you share a bit about the project first? Then a rough range can follow.`,
    `Happy to help. What are you looking to get done, and is there a timeline or budget you're working with? That makes it easy to point you to the right option.`,
  ],
  availability: (TAKING_CLIENTS ? [0, 1] : [1, 0]).map(i => [
    `Yes, Open Frame is taking new projects and could start ${NEXT_OPENING}. Want to grab a free 30-minute consult to talk it through?\n\n${CONSULT}`,
    `Open Frame is booked right now, with the next opening ${NEXT_OPENING}. Want a spot held? A quick consult locks it in:\n\n${CONSULT}`,
  ][i]).concat([`Possibly. What's your timeline, and what are you hoping to get done?`]),
  services: [
    `Open Frame does brand identity, websites, campaigns and content for mission-driven orgs and brands. What are you working on?`,
    `Here's some recent work:\n\n${WORK}\n\nIf it feels like a fit, book a free 30-minute consult:\n\n${CONSULT}`,
    `Sounds like something Open Frame can help with. Want to talk it through on a free 30-minute consult?\n\n${CONSULT}`,
  ],
  other: [
    `Thanks for reaching out. What are you working on? Happy to help where possible.`,
    `Thank you, that means a lot.`,
    `Want to talk it through? Book a free 30-minute consult:\n\n${CONSULT}`,
  ],
};

return $input.all().map(({ json: m }) => {
  const t = m.text.trim();
  let intent = 'other', reply = '', publicReply = '';
  const email = emailMatch(t);

  if (email) {
    intent = 'email';
    reply = `Thanks, you're on the list.\n\nIf you ever want help with a project, book a free 30-minute consult:\n\n${CONSULT}`;
  } else if (kitOn && has(t, ['kit'])) {
    intent = 'kit';
    reply = `Here's the Open Frame kit:\n\n${KIT_URL}\n\nWant one free template or guide a month? Reply with your email to get on the list.`;
    if (m.kind === 'comment') publicReply = 'Sent it to your DMs. If you don\'t see it, check your message requests.';
  } else if (m.kind === 'comment') {
    intent = 'comment';            // ordinary comments stay human, no ping
  } else if (has(t, ['stop', 'unsubscribe'])) {
    intent = 'unsubscribe';
    reply = "Done, you won't get any more emails from us.";
  } else if (has(t, ['price', 'prices', 'pricing', 'cost', 'costs', 'how much', 'rates?', 'budget', 'quote', 'charge'])) {
    intent = 'pricing';
  } else if (has(t, ['available', 'availability', 'taking', 'capacity', 'timeline', 'when can', 'start date', 'booked'])) {
    intent = 'availability';
  } else if (has(t, ['consult', 'call', 'meeting', 'book', 'booking', 'appointment'])) {
    intent = 'book';
    reply = `Great, pick any open time for a free 30-minute consult:\n\n${CONSULT}`;
  } else if (has(t, ['where', 'located', 'location', 'hours', 'timezone', 'time zone'])) {
    intent = 'location';
    reply = `Open Frame is in Minneapolis and Barcelona, available during US business hours, working with clients anywhere.\n\nBook a free consult here:\n\n${CONSULT}`;
  } else if (has(t, ['services', 'branding', 'brand', 'logo', 'website', 'web', 'marketing', 'social', 'design', 'help'])) {
    intent = 'services';
  }
  const opts = OPTIONS[intent] || [];
  const ping = opts.length > 0;
  const lead = ['pricing', 'availability', 'book', 'services', 'other'].includes(intent);
  return { json: { ...m, intent, email, reply, message: toMessage(reply), publicReply, lead, ping, short_id: shortId(m.id),
    option_1: opts[0] || '', option_2: opts[1] || '', option_3: opts[2] || '',
    status: ping ? 'needs_reply' : 'auto_replied' } };
});

// Add the sender's name, then let the local AI (Ollama on this Mac) answer DMs the rules didn't.
// ---- EDIT THESE ----
const AI_ON = true;
const MODEL = 'qwen2.5:7b';                       // any model pulled into Ollama
const BOOK_URL = 'https://calendly.com/grahamivy-co/30min';
const BRIEF = `You answer Instagram and Facebook DMs for Open Frame Design, a small design and marketing agency run by Graham.
Facts you can use:
- Helps mission-driven organizations, nonprofits and small brands stand out while staying true to who they are.
- Services: brand identity and logos, websites, social media content and campaigns, newsletters, marketing systems.
- Based in Minneapolis and Barcelona, works with clients anywhere, available during US business hours.
- Next step for any project is a free 30-minute consult with Graham, booked online.
- Portfolio: https://openframe.design
Rules:
- Sound like a friendly person texting: 1 to 3 short sentences, plain words, no emojis, no hype, no em dashes.
- Never quote prices, discounts or dates, and never promise anything. For those, say Graham will reply personally and suggest the free consult.
- Never invent facts beyond the list above. If you can't answer from it, set send to false.
- Set send to false for complaints, anything personal or sensitive, existing client work, or anything you are unsure about.
- Set book to true when booking the free consult is a natural next step.
Return JSON only: {"reply": "...", "send": true or false, "book": true or false}`;
// --------------------
const base = $('Classify + compose').item.json;
const p = $json || {};
const username = base.username || p.username || [p.first_name, p.last_name].filter(Boolean).join(' ') || '';
const out = { ...base, username, follows_us: p.is_user_follow_business === undefined ? '' : String(p.is_user_follow_business) };

// Same as in Classify: a reply ending in a link goes out as text + a tappable button.
const toMessage = text => {
  const m = String(text || '').match(/^([\s\S]*?)\s*\n\n(https?:\/\/\S+)\s*$/);
  if (!m || !m[1].trim()) return { text };
  const url = m[2];
  const title = url === 'https://openframe.design' ? 'See our work' : 'Book a free consult';
  return { attachment: { type: 'template', payload: { template_type: 'button', text: m[1].trim().replace(/:$/, '.'),
    buttons: [{ type: 'web_url', url, title }] } } };
};

if (AI_ON && out.kind === 'dm' && !out.reply && out.text.trim()) {
  try {
    const res = await this.helpers.httpRequest({ method: 'POST', url: 'http://localhost:11434/api/chat', json: true, timeout: 60000,
      body: { model: MODEL, stream: false, format: 'json', options: { temperature: 0.4 },
        messages: [{ role: 'system', content: BRIEF }, { role: 'user', content: out.text.slice(0, 1500) }] } });
    const ai = JSON.parse(res.message.content);
    let reply = String(ai.reply || '').trim().replace(/\s*—\s*/g, ', ');
    const risky = /\$|€|£|\d+\s*(%|dollars|euros|per hour|\/hr)/i.test(reply);
    if (reply) {
      if (ai.book) reply += `\n\n${BOOK_URL}`;
      out.option_1 = reply;
      if (ai.send === true && !risky) {
        const follow = ['pricing', 'availability'].includes(out.intent);   // still yours to follow up
        Object.assign(out, { reply, message: toMessage(reply), ping: follow, status: follow ? 'needs_reply' : 'auto_replied' });
      }
    }
    out.ai = ai.send === true && !risky ? 'sent' : 'draft';
  } catch (e) {
    out.ai = 'error: ' + String(e.message || e).slice(0, 80);   // Ollama off: falls back to the rules
  }
}
return { json: out };

// One row for the Inbox tab.
const m = $('Add sender info').item.json;
return { json: { id: m.id, received_at: m.received_at, platform: m.platform, kind: m.kind, sender_id: m.sender_id,
  username: m.username, text: m.text, intent: m.intent, auto_reply: m.reply, draft_reply: '',
  status: m.status, sent_at: m.reply ? new Date().toISOString() : '', notes: m.comment_id ? 'comment ' + m.comment_id : (m.ai ? 'ai ' + m.ai : ''),
  short_id: m.short_id, option_1: m.option_1, option_2: m.option_2, option_3: m.option_3 } };

const m = $json;
return { json: { subscribed_at: m.received_at, platform: m.platform, sender_id: m.sender_id, username: m.username,
  email: m.email, source: 'dm', asset_sent: 'yes', follows_us: m.follows_us } };

// Add inbound leads to the outreach tracker once. Existing rows are left alone.
const known = new Set($('Read Targets').all().map(r => String(r.json.handle || '').toLowerCase().replace('@', '')));
const seen = new Set();
const out = [];
for (const { json: m } of $('Lead?').all()) {
  const handle = (m.username || m.sender_id).toLowerCase();
  if (known.has(handle) || seen.has(handle)) continue;
  seen.add(handle);
  out.push({ json: { handle, name: m.username, type: 'inbound ' + m.platform, city: '', 'why them': 'Messaged us: ' + m.text.slice(0, 120),
    stage: 'replied', touches: 1, last_touch: m.received_at.slice(0, 10), next_step: 'Reply in Inbox tab', handle_check: '', notes: 'sender_id ' + m.sender_id } });
}
return out;

// Rows Graham approved: send if still inside Meta's 24-hour window, else mark expired.
const DAY = 24 * 60 * 60 * 1000;
const WORK = 'https://openframe.design';
const KIT_URL = '';
// Same as in Classify: a reply ending in a link is sent as text + a tappable button, so the link never wraps mid-word.
const toMessage = text => {
  const m = String(text || '').match(/^([\s\S]*?)\s*\n\n(https?:\/\/\S+)\s*$/);
  if (!m || !m[1].trim()) return { text };
  const url = m[2];
  const title = url === WORK ? 'See our work' : url === KIT_URL ? 'Get the kit' : 'Book a free consult';
  return { attachment: { type: 'template', payload: { template_type: 'button', text: m[1].trim().replace(/:$/, '.'),
    buttons: [{ type: 'web_url', url, title }] } } };
};

return $input.all()
  .filter(r => String(r.json.status).toLowerCase() === 'approved' && r.json.draft_reply)
  .filter(r => !String(r.json.notes || '').startsWith('public '))   // public comment replies: sent by the comment replies workflow
  .map(r => {
    const late = Date.now() - new Date(r.json.received_at).getTime() > DAY;
    const commentId = String(r.json.notes || '').startsWith('comment ') ? String(r.json.notes).slice(8) : '';
    return { json: { ...r.json, late, commentId, message: commentId ? { text: r.json.draft_reply } : toMessage(r.json.draft_reply) } };
  });

const row = $('Inside 24h?').item.json;
const ok = !$json.error;
return { json: { id: row.id, status: ok ? 'sent' : 'failed', sent_at: ok ? new Date().toISOString() : '',
  notes: ok ? row.notes : String(($json.error && $json.error.message) || 'send failed').slice(0, 200) } };
